using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;using System.Text.RegularExpressions;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {
 // Live configuration records references, never installs into the source game or Workshop.
 sealed class LauncherComponents {
  internal sealed class Selection {public string Id,SourceRoot;public bool Enabled;}
  internal sealed class State {public int Version=1;public List<Selection> Selections=new List<Selection>();public List<string> Managed=new List<string>();public Dictionary<string,bool> Decisions=new Dictionary<string,bool>();}
  internal sealed class Row {public string Id,Name,SourceRoot,Jar,Package,Sha256,ApprovalStamp,SourceEvidence,Warning="";public bool Enabled,Selected;public bool? Decision;public string[] Requires=new string[0],LoadAfter=new string[0],LoadBefore=new string[0],Conflicts=new string[0];}
  internal sealed class Capture {internal Row[] Rows;internal string[] Managed;internal byte[] Ordinary;internal string StateStamp;}
  readonly LauncherConfiguration context;readonly Version version;readonly string statePath;readonly Action<int,string> progress;
  internal static readonly string[] KnownIds=new[]{"ZombieBuddy","Viewpoint","PZVoxelStudioViewpoint","ShootToThrillMultiplayer","LaoYuTranslationJava","OrangeShootPresentation"}.Concat(ViewpointAddons.All.Select(a=>a.Id)).ToArray();
  internal LauncherComponents(LauncherConfiguration context,Version version,Action<int,string> progress=null){if(context==null||version==null)throw new ArgumentNullException();this.context=context;this.version=version;this.progress=progress;statePath=Path.Combine(context.ComponentsDirectory,"selection.json");}
  internal Version GameVersion{get{return version;}}
  internal LauncherConfiguration Context{get{return context;}}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=2097152};}
  internal static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  internal static string HashFile(string file){return HashFile(file,CancellationToken.None);}
  static string HashFile(string file,CancellationToken token){LauncherMaintenance.NoReparse(file);using(var sha=SHA256.Create())using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){var bytes=new byte[65536];int count;while((count=input.Read(bytes,0,bytes.Length))>0){token.ThrowIfCancellationRequested();sha.TransformBlock(bytes,0,count,null,0);}sha.TransformFinalBlock(new byte[0],0,0);return BitConverter.ToString(sha.Hash).Replace("-","").ToLowerInvariant();}}
  static string Full(string path){if(string.IsNullOrWhiteSpace(path)||!Path.IsPathRooted(path)||path.Any(char.IsControl))throw new IOException("组件来源必须是明确的本地目录。");string full=Path.GetFullPath(path).TrimEnd('\\','/');LauncherMaintenance.NoReparse(full);return full;}
  static string Id(string id){id=(id??"").TrimStart('\\');if(!SaveProfiles.Id(id))throw new IOException("组件 ID 无效。");return id;}
  State Read(){LauncherMaintenance.NoReparse(statePath);if(!File.Exists(statePath))return new State();if(new FileInfo(statePath).Length>2097152)throw new IOException("组件记录过大。");var s=Json().Deserialize<State>(File.ReadAllText(statePath));if(s==null||s.Version!=1||s.Selections==null||s.Decisions==null||s.Managed==null||s.Managed.Count>2000||s.Managed.Any(x=>Id(x)!=x)||s.Selections.Count>2000||s.Selections.Any(x=>x==null||Id(x.Id)!=x.Id||Full(x.SourceRoot)!=x.SourceRoot)||s.Selections.Select(x=>x.Id).Distinct().Count()!=s.Selections.Count)throw new IOException("组件记录无效，请检查所选配置。");return s;}
  internal static void Atomic(string path,byte[] bytes){LauncherMaintenance.NoReparse(path);Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+"."+Guid.NewGuid().ToString("N").Substring(0,8)+".tmp";try{using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(bytes,0,bytes.Length);f.Flush(true);}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  void Write(Action<State> change,CancellationToken token){if(context.Mode!="launcher")throw new IOException("请在启动器配置中修改组件。");string name="Local\\OrangeComponents-"+Hash(Encoding.UTF8.GetBytes(context.Root.ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("此配置的组件正在修改，请稍后重试。");token.ThrowIfCancellationRequested();var state=Read();change(state);token.ThrowIfCancellationRequested();context.Initialize();Atomic(statePath,Encoding.UTF8.GetBytes(Json().Serialize(state)));}finally{if(held)mutex.ReleaseMutex();}}}
  static string SourceStamp(string root){var files=new[]{Path.Combine(root,"mod.info")}.Concat(Directory.GetDirectories(root).Where(p=>Path.GetFileName(p)=="common"||Regex.IsMatch(Path.GetFileName(p),@"^\d+(\.\d+)*$")).Select(p=>Path.Combine(p,"mod.info"))).Where(File.Exists).OrderBy(p=>p,StringComparer.OrdinalIgnoreCase).ToArray();return Hash(Encoding.UTF8.GetBytes(string.Join("\n",files.Select(p=>{LauncherMaintenance.NoReparse(p);if(new FileInfo(p).Length>262144)throw new IOException("模组元数据过大。");var seen=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in File.ReadAllLines(p)){int at=line.IndexOf('=');if(at<=0)continue;string key=line.Substring(0,at).Trim(),value=line.Substring(at+1).Trim(),prior;if(!Regex.IsMatch(key,@"^(id|require|java.*|ZBVersion.*|versionMin|versionMax)$",RegexOptions.IgnoreCase))continue;if(seen.TryGetValue(key,out prior)&&prior!=value)throw new IOException("模组资料包含不同的重复加载声明："+p+" · "+key);seen[key]=value;}return p+"="+HashFile(p);})))) ;}
  static string ApprovalKey(Row row){return Hash(Encoding.UTF8.GetBytes(row.Id+"\n"+row.SourceRoot.ToUpperInvariant()+"\n"+row.Jar.ToUpperInvariant()+"\n"+row.Package+"\n"+row.Sha256));}
  internal Row Inspect(string sourceRoot,string id,CancellationToken token){token.ThrowIfCancellationRequested();sourceRoot=Full(sourceRoot);id=Id(id);if(!Directory.Exists(sourceRoot))throw new IOException(id+"：来源目录已不存在："+sourceRoot);string sourceEvidence=SourceStamp(sourceRoot);string mods=Path.GetDirectoryName(sourceRoot);if(!Path.GetFileName(mods).Equals("mods",StringComparison.OrdinalIgnoreCase))throw new IOException(id+"：请选择 mods 下的具体模组目录。");
   // Reuse the existing version-aware metadata/JAR resolver with an explicit selected folder.
   var budget=new LaunchReadBudget(16777216,10000);budget.Checkpoint=(file,size)=>token.ThrowIfCancellationRequested();var f=ViewpointAddons.ResolveSource(Path.GetDirectoryName(mods),id,version,budget,sourceRoot);
   foreach(string folder in new[]{sourceRoot}.Concat(Directory.GetDirectories(sourceRoot).Where(p=>Path.GetFileName(p)=="common"||Regex.IsMatch(Path.GetFileName(p),@"^\d+(\.\d+)*$")))){var m=ViewpointAddons.Metadata(Path.Combine(folder,"mod.info"),budget);string declared;if(m.TryGetValue("id",out declared)&&Id(declared)!=id)throw new IOException(id+"：同一目录声明了不同模组身份。");}
   string name,pkg,require;f.Metadata.TryGetValue("name",out name);(f.JavaMetadata??f.Metadata).TryGetValue("javaPkgName",out pkg);f.Metadata.TryGetValue("require",out require);if(f.Jar!=null&&!Regex.IsMatch(pkg??"",@"^[A-Za-z_$][A-Za-z0-9_$]*(\.[A-Za-z_$][A-Za-z0-9_$]*)*$"))throw new IOException(id+"：Java 包名无效。");
   JavaComponents.Versions(version.ToString(),f.Metadata,"versionMin","versionMax",true);JavaComponents.Versions("2.3.4",f.JavaMetadata??f.Metadata,"ZBVersionMin","ZBVersionMax",false);
   if(f.Jar==null&&f.Metadata.Keys.Any(k=>Regex.IsMatch(k,"^javaJarFile[0-9]+$",RegexOptions.IgnoreCase)))throw new IOException(id+"：此模组需要 Buddy 3 的编号 Java 声明；当前独立运行支持 Buddy 2.3.4。");
   var row=new Row{Id=id,Name=name??id,SourceRoot=sourceRoot,Jar=f.Jar,Package=pkg??"",Requires=Edges(f.Metadata,"require"),LoadAfter=Edges(f.Metadata,"loadAfter"),LoadBefore=Edges(f.Metadata,"loadBefore"),Conflicts=Edges(f.Metadata,"incompatible")};if(f.Jar!=null){if(new FileInfo(f.Jar).Length>134217728)throw new IOException(id+"：Java 文件超过128MB读取上限。");string beforeHash=HashFile(f.Jar,token);JavaComponents.ValidateJarIdentity(f.Jar,row.Package);row.Sha256=HashFile(f.Jar,token);if(beforeHash!=row.Sha256)throw new IOException(id+"：Java 文件正在更新，请重试。");row.ApprovalStamp=ApprovalKey(row);}if(sourceEvidence!=SourceStamp(sourceRoot))throw new IOException(id+"：模组资料正在更新，请重试。");row.SourceEvidence=sourceEvidence;token.ThrowIfCancellationRequested();return row;
  }
  Row[] Rows(State state,CancellationToken token){int count=0;return state.Selections.Select(s=>{token.ThrowIfCancellationRequested();if(progress!=null)progress(-1,"正在核对组件 · 已处理 "+count+++" / "+state.Selections.Count+" · "+s.Id);Row row;try{row=Inspect(s.SourceRoot,s.Id,token);bool decision;if(row.Jar!=null&&state.Decisions.TryGetValue(ApprovalKey(row),out decision))row.Decision=decision;}catch(OperationCanceledException){throw;}catch(Exception ex){row=new Row{Id=s.Id,Name=s.Id,SourceRoot=s.SourceRoot,Warning=ex.Message};}row.Enabled=s.Enabled;row.Selected=true;return row;}).ToArray();}
  internal Row[] List(CancellationToken token){token.ThrowIfCancellationRequested();return Rows(Read(),token);}
  static string[] Edges(Dictionary<string,string> metadata,string key){string value;metadata.TryGetValue(key,out value);return (value??"").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(x=>Id(x.Trim())).Distinct().ToArray();}
  internal string[] ManagedIds(){var s=Read();return KnownIds.Concat(s.Managed).Concat(s.Selections.Select(x=>x.Id)).Distinct().ToArray();}
  internal void Select(string sourceRoot,string id,bool enabled,CancellationToken token){var row=Inspect(sourceRoot,id,token);Write(s=>{if(!s.Managed.Contains(row.Id))s.Managed.Add(row.Id);var prior=s.Selections.Find(x=>x.Id==row.Id);if(prior==null)s.Selections.Add(new Selection{Id=row.Id,SourceRoot=row.SourceRoot,Enabled=enabled});else{prior.SourceRoot=row.SourceRoot;prior.Enabled=enabled;}},token);}
  internal void SetEnabled(string id,bool enabled,CancellationToken token,string expectedSource=null){id=Id(id);Write(s=>{var selected=s.Selections.SingleOrDefault(x=>x.Id==id);if(selected==null)throw new IOException(id+"：请先选择组件来源。");if(expectedSource!=null&&!VersionLibrary.Same(selected.SourceRoot,Full(expectedSource)))throw new IOException(id+"：此来源不是当前配置所选组件。");if(enabled)Inspect(selected.SourceRoot,id,token);selected.Enabled=enabled;},token);}
  internal void Uninstall(string id,CancellationToken token,string expectedSource=null){id=Id(id);Write(s=>{if(expectedSource!=null&&!s.Selections.Any(x=>x.Id==id&&VersionLibrary.Same(x.SourceRoot,Full(expectedSource))))throw new IOException(id+"：此来源不是当前配置所选组件。");s.Selections.RemoveAll(x=>x.Id==id);},token);}
  internal void Decide(string id,string expectedStamp,bool allow,CancellationToken token){id=Id(id);Write(s=>{var row=Rows(s,token).SingleOrDefault(x=>x.Id==id);if(row==null||!row.Enabled||row.Jar==null||row.Warning!=""||row.ApprovalStamp!=expectedStamp)throw new IOException(id+"：Java 文件或选择已变化，请刷新后授权。");s.Decisions[ApprovalKey(row)]=allow;},token);}
  internal Capture CaptureCurrent(CancellationToken token){var state=Read();var capture=new Capture{StateStamp=Hash(Encoding.UTF8.GetBytes(Json().Serialize(state))),Rows=Rows(state,token),Managed=KnownIds.Concat(state.Managed).Concat(state.Selections.Select(x=>x.Id)).Distinct().ToArray(),Ordinary=File.Exists(context.DefaultModsPath)?File.ReadAllBytes(context.DefaultModsPath):null};RequireCurrent(capture);return capture;}
  internal void RequireCurrent(Capture capture){if(Hash(Encoding.UTF8.GetBytes(Json().Serialize(Read())))!=capture.StateStamp||Hash(capture.Ordinary??new byte[0])!=Hash(File.Exists(context.DefaultModsPath)?File.ReadAllBytes(context.DefaultModsPath):new byte[0]))throw new IOException("启动配置已变化，请重新启动。");foreach(var row in capture.Rows.Where(x=>x.Enabled&&x.Warning==""))if(row.SourceEvidence!=SourceStamp(row.SourceRoot))throw new IOException(row.Name+"：模组资料已更新，请重试。");}
  internal ModConfigurations.SortResult PlanEnabled(SaveProfiles.Entry[] ordinaryCatalog,CancellationToken token){return PlanEnabled(CaptureCurrent(token),ordinaryCatalog,token,null);}
  internal ModConfigurations.SortResult PlanEnabled(Capture capture,SaveProfiles.Entry[] ordinaryCatalog,CancellationToken token,string[] ordinaryOverride){var rows=capture.Rows.Where(x=>x.Enabled).ToArray();var managed=capture.Managed.Concat((ordinaryCatalog??new SaveProfiles.Entry[0]).Where(entry=>entry.javaComponent).Select(entry=>Id(entry.id))).Distinct().ToArray();string[] ordinary=(ordinaryOverride??SaveProfiles.DefaultMods(capture.Ordinary)).Where(x=>!managed.Contains(Id(x))).ToArray();var entries=(ordinaryCatalog??new SaveProfiles.Entry[0]).Where(x=>!managed.Contains(Id(x.id))).ToList();foreach(var row in rows){if(row.Warning!="")throw new IOException(row.Warning);entries.Add(new SaveProfiles.Entry{id=row.Id,requires=row.Jar!=null&&row.Id!="ZombieBuddy"?row.Requires.Concat(new[]{"ZombieBuddy"}).Distinct().ToArray():row.Requires,loadAfter=row.LoadAfter,loadBefore=row.LoadBefore,conflicts=row.Conflicts});}var requested=rows.Select(x=>x.Id).Concat(ordinary).ToList();var queue=new Queue<string>(rows.Select(x=>x.Id));var visited=new HashSet<string>();while(queue.Count>0){token.ThrowIfCancellationRequested();string id=queue.Dequeue();if(!visited.Add(id))continue;var found=entries.Where(e=>e.id.TrimStart('\\')==id).ToArray();if(found.Length!=1)continue;foreach(string raw in found[0].requires??new string[0]){string dependency=Id(raw);var sources=entries.Where(e=>e.id.TrimStart('\\')==dependency).ToArray();bool selected=rows.Any(r=>r.Id==dependency);if(sources.Length!=1||!selected&&(sources[0].componentManaged||sources[0].javaComponent||JavaComponents.HasJavaMetadata(sources[0].metadata)))throw new IOException("所选组件依赖 "+dependency+" 尚无唯一可用的当前来源；Java 依赖须在组件中心选择并启用。");if(!requested.Any(value=>Id(value)==dependency))requested.Add(dependency);queue.Enqueue(dependency);}}return ModConfigurations.Order(requested.ToArray(),entries,new List<string>(),new HashSet<string>(ordinary));}
  string[] OrdinaryManaged(IEnumerable<string> ids,CancellationToken token){
   var managed=ManagedIds();var requested=ids.Select(Id).Except(managed).Distinct().ToArray();if(requested.Length==0)return managed;
   var source=new Engine(context.Game,context.User,context.DataDirectory,true,null,null,false){ModCatalogVersion=version};var budget=new LaunchReadBudget(67108864,100000);int count=0;
   budget.Checkpoint=(file,size)=>{token.ThrowIfCancellationRequested();if(progress!=null&&(++count==1||count%20==0))progress(-1,"正在核对普通模组 · 已读取 "+count+" 项");};
   var catalog=SaveProfiles.SnapshotEntries(source,requested,new List<string>(),budget);token.ThrowIfCancellationRequested();if(budget.Incomplete)throw new IOException("普通模组来源未能完整读取，请重新核对后保存。");
   return managed.Concat(catalog.Entries.Where(entry=>entry.javaComponent).Select(entry=>Id(entry.id))).Distinct().ToArray();
  }
  static string[] EffectiveOrdinary(byte[] bytes,string[] managed){return SaveProfiles.DefaultMods(bytes).Where(x=>!managed.Contains(Id(x))).ToArray();}
  internal string[] OrdinaryIds(){byte[] bytes=context.DefaultModsBytes();return EffectiveOrdinary(bytes,OrdinaryManaged(SaveProfiles.DefaultMods(bytes),CancellationToken.None));}
  internal void SaveOrdinary(string[] ids,CancellationToken token){if(context.Mode!="launcher")throw new IOException("请在启动器配置中修改普通模组。");if(ids==null||ids.Length>2000||ids.Any(x=>!SaveProfiles.Id(x))||ids.Distinct().Count()!=ids.Length)throw new IOException("普通模组清单无效。");string name="Local\\OrangeOrdinary-"+Hash(Encoding.UTF8.GetBytes(context.Root.ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("此配置的普通模组清单正在修改，请稍后重试。");token.ThrowIfCancellationRequested();context.Initialize();byte[] before=File.ReadAllBytes(context.DefaultModsPath);var persisted=SaveProfiles.DefaultMods(before);if(persisted.SequenceEqual(ids))return;var managed=OrdinaryManaged(persisted.Concat(ids),token);if(EffectiveOrdinary(before,managed).SequenceEqual(ids))return;if(ids.Select(Id).Any(managed.Contains))throw new IOException("组件由组件中心管理，请勿添加到普通模组清单。");token.ThrowIfCancellationRequested();Atomic(context.DefaultModsPath,SaveProfiles.ReplaceDefaultMods(before,ids));}finally{if(held)mutex.ReleaseMutex();}}}

 }
}
